import { getChatGPTUser } from "./chatgpt-auth";
import StudyTracker from "./study-tracker";
import LearningProgressOverview from "./learning-progress-overview";

export default async function Home() {
  const user = await getChatGPTUser();
  const today = new Intl.DateTimeFormat("sv-SE", {
    timeZone: "Europe/Berlin",
  }).format(new Date());

  return <><LearningProgressOverview /><p className="learning-previous-plan-label">Bisheriger Forschungsplan mit eigenem Zeitplan und Verlauf</p><StudyTracker displayName={user?.displayName ?? null} today={today} /></>;
}
